<template><view class="page ui-page" v-if="order"><view class="status-hero"><text>订单{{statusText(order.status)}}</text><text class="order-no">{{order.orderNo}}</text></view><view class="card ui-card"><view class="row"><text>收货地址</text><text class="address">{{order.receiverName||'-'}} {{order.receiverPhone||''}} {{order.receiverAddress||''}}</text></view></view><view class="card ui-card"><view v-for="item in order.items||[]" :key="item.id||item.skuId" class="item"><text>{{item.goodsName}} {{item.specText||''}} ×{{item.quantity}}</text><text>¥{{item.subtotalAmount||item.price}}</text></view><view class="total">实付 ¥{{order.payAmount}}</view></view><view v-if="error" class="error">{{error}}</view><view class="actions"><button v-if="order.status==='PENDING_PAY'" :loading="actionLoading" :disabled="actionLoading" @tap="cancel">取消订单</button><button v-if="order.status==='SHIPPED'" class="primary ui-primary" :loading="actionLoading" :disabled="actionLoading" @tap="receive">确认收货</button><button v-if="canRefund" :loading="actionLoading" :disabled="actionLoading" @tap="refund">申请退款</button></view></view><view v-else-if="!loading" class="ui-empty">{{error||'订单不存在'}}</view></template>
<script setup lang="ts">import {computed,ref} from 'vue';import {apiRequest,toast} from '@mall/uni-shared';const id=Number((uni.getEnterOptionsSync?.() as any)?.query?.id||0);const order=ref<any>(),loading=ref(false),actionLoading=ref(false),error=ref('');const canRefund=computed(()=>['PAID','PENDING_SHIP','SHIPPED'].includes(order.value?.status));const statusText=(s:string)=>({PENDING_PAY:'待支付',PAID:'已支付',PENDING_SHIP:'待发货',SHIPPED:'已发货',COMPLETED:'已完成',REFUNDING:'退款中',REFUNDED:'已退款',CLOSED:'已关闭'} as any)[s]||s;async function load(){if(!id){error.value='订单参数无效';return}loading.value=true;try{order.value=await apiRequest({url:`/api/c/order/${id}`})}catch(e:any){error.value=e.message||'订单加载失败'}finally{loading.value=false}}async function cancel(){if(actionLoading.value)return;actionLoading.value=true;try{await apiRequest({url:`/api/c/order/${id}/cancel`,method:'POST'});toast('订单已取消','success');await load()}catch(e:any){toast(e.message||'取消订单失败')}finally{actionLoading.value=false}}async function receive(){if(actionLoading.value)return;actionLoading.value=true;try{await apiRequest({url:`/api/c/order/${id}/confirm-receive`,method:'POST'});toast('已确认收货','success');await load()}catch(e:any){toast(e.message||'确认收货失败')}finally{actionLoading.value=false}}async function refund(){if(actionLoading.value)return;actionLoading.value=true;try{const r:any=await uni.showModal({title:'申请退款',content:'将按订单全额申请退款，是否继续？'});if(!r.confirm)return;await apiRequest({url:'/api/c/refund',method:'POST',data:{orderId:id,reasonCode:'USER',reasonDesc:'用户申请退款',images:[]}});toast('退款申请已提交','success');await load()}catch(e:any){toast(e.message||'退款申请失败')}finally{actionLoading.value=false}}load();</script>
<style scoped>.status-hero{margin:-4rpx 0 20rpx;padding:32rpx;background:linear-gradient(135deg,#173d4f,#168f86);border-radius:28rpx;color:#fff;font-size:36rpx;font-weight:750}.order-no{display:block;margin-top:10rpx;font-size:22rpx;opacity:.72;font-weight:400}.card{padding:28rpx;margin-bottom:18rpx}.row,.item{display:flex;justify-content:space-between;gap:20rpx;padding:16rpx 0;font-size:26rpx}.address{max-width:72%;text-align:right;color:#59677d}.item{border-bottom:1rpx solid #eef1f5}.total{text-align:right;color:#e85d4a;font-size:34rpx;font-weight:750;margin-top:20rpx}.actions{display:flex;gap:20rpx}.actions button{flex:1;border-radius:18rpx;font-size:27rpx}.error{padding:30rpx;color:#d9534f;text-align:center}</style>
